<?php
namespace App\Http\Controllers;
use App\Models\Peminjamans; use App\Models\Alats; use App\Support\CatatLog; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class PeminjamanController extends Controller {
 public function index(){abort_unless(in_array(auth()->user()->role,['admin','peminjam'],true),403);$q=Peminjamans::with(['user','details.alat'])->latest();if(auth()->user()->role==='peminjam')$q->where('user_id',auth()->id());return view('peminjamans.index',['peminjamen'=>$q->paginate(15)]);}
 public function create(){abort_unless(in_array(auth()->user()->role,['admin','peminjam'],true),403);return view('peminjamans.form',['users'=>auth()->user()->role==='admin'?\App\Models\User::where('role','peminjam')->get():collect([auth()->user()]),'alats'=>Alats::orderBy('nama_alat')->get()]);}
 public function store(Request $request){$admin=auth()->user()->role==='admin';abort_unless($admin||auth()->user()->role==='peminjam',403);$data=$request->validate(['user_id'=>$admin?'required|exists:users,id,role,peminjam':'nullable','tanggal_pinjam'=>'required|date','tanggal_kembali_rencana'=>'nullable|date|after_or_equal:tanggal_pinjam','items'=>'required|array|min:1','items.*.alat_id'=>'required|exists:alats,id','items.*.jumlah'=>'required|integer|min:1']);$userId=$admin?$data['user_id']:auth()->id();DB::transaction(function()use($data,$userId,$admin){$p=Peminjamans::create(['user_id'=>$userId,'tanggal_pinjam'=>$data['tanggal_pinjam'],'tanggal_kembali_rencana'=>$data['tanggal_kembali_rencana']??null,'status_peminjaman'=>$admin?'disetujui':'menunggu']);foreach($data['items'] as $i=>$item){$a=Alats::lockForUpdate()->findOrFail($item['alat_id']);if($admin&&$a->stok<$item['jumlah'])throw ValidationException::withMessages(["items.$i.jumlah"=>"Stok {$a->nama_alat} tersisa {$a->stok}, tidak cukup."]);if($admin)$a->decrement('stok',$item['jumlah']);$p->details()->create(['alat_id'=>$a->id,'jumlah'=>$item['jumlah'],'status'=>false]);}});CatatLog::buat('Peminjaman dibuat');return redirect()->route('peminjaman.index')->with('sukses',$admin?'Peminjaman disetujui dan stok dikurangi.':'Pengajuan peminjaman terkirim.');}
 public function destroy(Peminjamans $peminjaman){abort_unless(auth()->user()->role==='admin',403);$deleted=DB::transaction(function()use($peminjaman){$p=Peminjamans::whereKey($peminjaman->id)->lockForUpdate()->with('details')->firstOrFail();if($p->details->contains(fn($detail)=>$detail->status))return false;foreach($p->details as $detail){$alat=Alats::lockForUpdate()->findOrFail($detail->alat_id);$alat->increment('stok',$detail->jumlah);}$p->delete();return true;});if(!$deleted)return back()->with('error','Sudah ada alat yang dikembalikan, transaksi tidak dapat dihapus.');CatatLog::buat('Peminjaman dihapus');return back()->with('sukses','Peminjaman dihapus dan stok dikembalikan.');}
}
